H,W=27,23
G=[[8]*W for _ in range(H)]
frames=[(1,5,2),(7,11,4),(13,17,3),(19,23,1)]
for r0,r1,col in frames:
    for c in range(1,12):
        G[r0][c]=col; G[r1][c]=col
    for r in range(r0,r1+1):
        G[r][1]=col; G[r][11]=col
# Interior markers: one per matching-color external component, placed in the center row at the rightmost available slots.
for r, col, slots in [(3,2,[7,9]), (9,4,[3,5,7,9]), (15,3,[9]), (21,1,[9])]:
    for c in slots: G[r][c]=col
print(len(G), len(G[0]))
for row in G: print(' '.join(map(str,row)))
